member.example:
    Uses Localization class directly.

var defaultString = Localization.GetLocalString("Hello");
var jpnString = Localization.GetLocalString("Welcome", "jpn");

    Uses this extension method.

var defaultString = "Hello".ToLocalString();
var jpnString = "Welcome".ToLocalString("jpn");
var nullString = ((string) null).ToLocalString(); // Won't throw NullReferenceException.

